# Executed inside src/build_report.py. E1 PCA section; numbers loaded from results/extE1_*.csv.
section("Extension E1: PCA")
E1S, E1L, E1K, E1M, E1D, E1I, E1P = "results/extE1_pca_summary.csv", "results/extE1_loadings.csv", "results/extE1_hormone_corr.csv", "results/extE1_metrics_all.csv", "results/extE1_deltas.csv", "results/extE1_identity_check.csv", "results/extE1_pcr_k.csv"
SCRIPT.update({E1S: "src/ext_E1_pca.py", E1L: "src/ext_E1_pca.py", E1K: "src/ext_E1_pca.py", E1M: "src/ext_E1_pca.py (src/extlib.py)", E1D: "src/ext_E1_pca.py (src/extlib.py)", E1I: "src/ext_E1_pca.py", E1P: "src/ext_E1_pca.py"})
e = []; a = e.append
a("### 8.1 E1: Principal component analysis from scratch (SVD)\n")
a("Math note: `docs/math/E1_pca.md`. PCA = standardise, centre, SVD; fitted on **training rows only** at every level of the nested CV (test rows are only projected); results in `results/extE1_*.csv`.\n")
hk = lambda s_, sc, g: val(E1K, dict(sample=s_, scale=sc, group=g), "pearson_r", "{:.2f}", label=f"r(E2,P) {s_} {sc} {g}")
nh = lambda s_, g: val(E1K, dict(sample=s_, scale="log1p", group=g), "n_rows", "{:.0f}", label=f"n rows r(E2,P) {s_} {g}")
a(f"**Collinearity of estradiol and progesterone.** Pearson correlation (pooled, {nn('pooled')}): raw {hk('pooled', 'raw', 'all rows')}, log1p {hk('pooled', 'log1p', 'all rows')} (Spearman {val(E1K, dict(sample='pooled', scale='log1p', group='all rows'), 'spearman_rho', '{:.2f}', label='spearman log1p pooled')}); longitudinal ({nn('long')}) log1p {hk('long', 'log1p', 'all rows')}. Within phase (pooled, log1p): menses {hk('pooled', 'log1p', 'menses')} (n = {nh('pooled', 'menses')} rows), peri-ovulatory {hk('pooled', 'log1p', 'peri-ovulatory')} (n = {nh('pooled', 'peri-ovulatory')}), luteal {hk('pooled', 'log1p', 'luteal')} (n = {nh('pooled', 'luteal')}). For two variables the first principal component captures a share (1+|r|)/2 of their variance: {val(E1K, dict(sample='pooled', scale='log1p', group='all rows'), 'pc1_share_of_two_hormones', '{:.2f}', label='PC1 share two hormones pooled log1p')} here. The two hormones are only moderately correlated, so they are not strongly collinear; the strong dependence of hormones on **phase** (not on each other) is what matters for prediction.\n")
a("**Explained variance, rank and conditioning** (standardised features of each set, whole sample, descriptive):\n")
a("| Sample (n) | Feature set | Components 1 / 2 / 3 / ... explained-variance ratio | Numerical rank (of p) | Condition number of the correlation matrix |\n|---|---|---|---|---|")
for s_ in ["pooled", "long"]:
    for fs in ["B", "C", "D2", "D"]:
        g = df(E1S); g = g[(g["sample"] == s_) & (g.fset == fs)]; p_ = len(g)
        evr = " / ".join(val(E1S, dict(sample=s_, fset=fs, component=float(j + 1)), "explained_var_ratio", "{:.2f}", label=f"explained variance {s_} {fs} PC{j+1}") for j in range(p_))
        a(f"| {s_} ({nn(s_)}) | {fs} | {evr} | {val(E1S, dict(sample=s_, fset=fs, component=1.0), 'numerical_rank', '{:.0f}', label=f'rank {s_} {fs}')} of {p_} | {val(E1S, dict(sample=s_, fset=fs, component=1.0), 'kappa_corr_matrix', '{:.1f}', label=f'kappa corr {s_} {fs}')} |")
table("T-E1-pca", "explained variance, rank and conditioning", E1S, "src/ext_E1_pca.py")
a(f"\nAll sets have full numerical rank (no exactly redundant features); no component dominates (set D pooled: first component {val(E1S, dict(sample='pooled', fset='D', component=1.0), 'explained_var_ratio', '{:.2f}', label='PC1 explained D pooled')}, first three together {val(E1S, dict(sample='pooled', fset='D', component=3.0), 'cum_explained', '{:.2f}', label='cumulative explained D pooled PC3')}). Loadings of the first three components for set D (pooled, {nn('pooled')}):\n")
a("| Feature | PC1 | PC2 | PC3 |\n|---|---|---|---|")
for f_ in ["peri-ov", "luteal", "log E2", "log P", "PSST", "BDI", "BAI"]:
    a(f"| {f_} | " + " | ".join(val(E1L, dict(sample="pooled", fset="D", component=float(j), feature=f_), "loading", "{:+.2f}", label=f"loading D pooled PC{j} {f_}") for j in [1, 2, 3]) + " |")
table("T-E1-loadings", "loadings of set D", E1L, "src/ext_E1_pca.py")
_ld = lambda j, f_: float(df(E1L).query("sample == 'pooled' and fset == 'D' and component == @j and feature == @f_").loading.iloc[0])
claim(abs(_ld(1, "luteal")) > 0.5 and abs(_ld(1, "log P")) > 0.5 and abs(_ld(2, "BDI")) > 0.5 and abs(_ld(2, "BAI")) > 0.5 and abs(_ld(3, "log E2")) > 0.5, "interpretation of the loadings")
a("\nReading the loadings (signs are arbitrary): the first component is a **luteal-phase / progesterone axis** (luteal and log P carry the largest loadings), the second a **questionnaire axis** (BDI, BAI and, less, PSST), the third a **peri-ovulatory / estradiol axis** (log E2 and the peri-ovulatory dummy).\n")
mx_id = float(df(E1I).max_abs_pred_diff.max()); claim(mx_id < 1e-9, "ridge on all PCs equals ridge on raw")
a(f"**Identity check.** Ridge on **all** principal components must equal ridge on the raw standardised features (rotation invariance). Over {agg(E1I, '', None, 'count', '{:.0f}', label='identity-check configurations')} configurations (3 samples x 3 targets x 4 sets) the largest difference between out-of-fold predictions was {agg(E1I, '', 'max_abs_pred_diff', 'max', '{:.1e}', label='max |prediction difference| ridge on PCs vs raw')}, and the same lambda was selected in {calc('mean share of folds with same lambda', float(df(E1I).same_lambda_rate.mean()), '{:.3f}', E1I, 'mean of same_lambda_rate over configurations')} of the folds.\n")
a(f"**Predictive comparison, pooled sample** ({nn('pooled')}, leave-one-woman-out, nested CV; R2 versus the mean baseline [95% CI over women]). Raw = Phase 4 models on the standardised features; PCs = the same models on principal components fitted in the training fold:\n")
a("| Model | Set | positive affect | DRSP psychological | state anxiety |\n|---|---|---|---|---|")
for mname, lab in [("ridge", "ridge, raw"), ("ridge_pcs", "ridge, all PCs"), ("pcr", "PC regression (k by nested CV)"), ("rf", "random forest, raw"), ("rf_pcs", "random forest, PCs")]:
    for fs in ["B", "C", "D2", "D"]: a(f"| {lab} | {fs} | " + " | ".join(ci(E1M, dict(sample="pooled", target=t, model=mname, fset=fs), "R2_oos", "{:+.3f}", label=f"E1 {mname} {fs} {t} pooled") for t in ["pos_affect", "drsp_psych", "stai"]) + " |")
table("T-E1-ML", "R2_oos of raw vs PCA-based models (pooled)", E1M, "src/ext_E1_pca.py")
dd = df(E1D); dd = dd[dd.metric == "RMSE"]; sel = lambda pre, extra="": agg(E1D, f"metric == 'RMSE' and first.str.startswith('{pre}')" + extra, None, "count", "{:.0f}", label=f"E1 {pre} comparisons {extra}")
n_pcr, n_rf = sel("pcr"), sel("rf_pcs"); claim(int(sel('pcr', ' and delta < 0 and hi < 0')) == 0, 'PC regression never significantly better than raw ridge')
a(f"\n**Paired differences in RMSE** (PC-based minus raw model, same women resampled; negative = PCs better), across {n_pcr} comparisons each ({calc('E1 samples', dd['sample'].nunique(), '{:.0f}', E1D, 'unique sample')} samples x {calc('E1 targets', dd.target.nunique(), '{:.0f}', E1D, 'unique target')} targets x {calc('E1 sets', dd['first'].str.split('/').str[1].nunique(), '{:.0f}', E1D, 'unique feature sets in the first column')} feature sets): PC regression versus ridge on raw features: median change {calc('E1 pcr median delta RMSE', float(dd[dd['first'].str.startswith('pcr')].delta.median()), '{:+.4f}', E1D, 'median delta, first starts with pcr')} (range {calc('E1 pcr min', float(dd[dd['first'].str.startswith('pcr')].delta.min()), '{:+.3f}', E1D, 'min')} to {calc('E1 pcr max', float(dd[dd['first'].str.startswith('pcr')].delta.max()), '{:+.3f}', E1D, 'max')}); significant improvement in {sel('pcr', ' and delta < 0 and hi < 0')} and significant deterioration in {sel('pcr', ' and delta > 0 and lo > 0')} of {n_pcr}. Random forest on PCs versus raw: median change {calc('E1 rf_pcs median delta RMSE', float(dd[dd['first'].str.startswith('rf_pcs')].delta.median()), '{:+.4f}', E1D, 'median delta, first starts with rf_pcs')}; significant improvement in {sel('rf_pcs', ' and delta < 0 and hi < 0')} and deterioration in {sel('rf_pcs', ' and delta > 0 and lo > 0')} of {n_rf}. The number of components kept by PC regression (median over folds, pooled, DRSP, set D) was {val(E1P, dict(sample='pooled', target='drsp_psych', fset='D'), 'median_k_components', '{:.0f}', label='median k pcr D pooled drsp')} of {val(E1S, dict(sample='pooled', fset='D', component=1.0), 'n_features', '{:.0f}', label='n features D')}.\n")
a("**Reading.** With all components kept PCA changes nothing (identity check). Dropping components (PC regression) or rotating the data for trees gives no systematic gain (no significant improvement for PC regression). A plausible reason, not tested here, is that PCA ignores the outcome, so the directions of high predictor variance need not be the ones that carry mood information; and the two hormones are only moderately correlated, leaving little to compress. In this data PCA is a tool for understanding the structure of the predictors, not for improving prediction. Full tables for all three samples: `results/extE1_metrics_all.csv`, `results/extE1_deltas.csv`.\n")
EXT.append("\n".join(e))
